def translations(A,B):
 from collections import Counter
 c=Counter((a[0]-b[0],a[1]-b[1]) for a in A for b in B)
 return sorted([(n,dr,dc) for (dr,dc),n in c.items() if n>=1], reverse=True)
for name,m in [('6',M6),('1',M1),('3',M3),('5',M5)]: print(name,translations(M4,m))
